command:. .gnomish/lib/task-change.sh
review="$reports/review-specs.md"
[ -f "$review" ] || { echo "$review is missing - the review-specs stage left it there; restore it from git"; exit 1; }
open=$(grep -nE '^- Status: open' "$review" || true)
[ -z "$open" ] || { echo "$open"; echo "these findings are still open - fix or reject each one, see stages/fix-specs/instructions.md"; exit 1; }
bad=$(grep -nE '^- Status: ' "$review" | grep -vE '^[0-9]+:- Status: (fixed|rejected \((false-positive|contradicts-spec|harmful|out-of-scope|not-worth-it)\))$' || true)
[ -z "$bad" ] || { echo "$bad"; echo "a status reads 'fixed' or 'rejected (false-positive|contradicts-spec|harmful|out-of-scope|not-worth-it)'"; exit 1; }
findings=$(grep -cE '^### R[0-9]+ — ' "$review" || true)
resolutions=$(grep -cE '^- Resolution: .{20,}' "$review" || true)
[ "$resolutions" = "$findings" ] || { echo "$review has $findings findings but $resolutions '- Resolution:' lines of substance - every finding gets one, right after its Status"; exit 1; }

command:. .gnomish/lib/task-change.sh
# Where the task branch started: the box has no origin, so never origin/main.
start=$(git log --format='%H %s' | awk '$2 == "gnomish:" && $3 == "task" && $4 == "started" { print $1; exit }')
base=$(git rev-parse "$start^" 2>/dev/null || git merge-base HEAD origin/main 2>/dev/null) || { echo "cannot tell where this task branch started: no 'gnomish: task started' commit and no origin/main"; exit 1; }
outside=$({ git diff --name-only "$base"; git ls-files -o --exclude-standard; } | sort -u | grep -v "^$change/" | grep -vxF "$record" | grep -vxF "$reports/review-specs.md" | grep -v '^\.gnomish-task/' || true)
[ -z "$outside" ] || { echo "$outside"; echo "the fix-specs stage revises only files under $change/ and the resolutions in $reports/review-specs.md - if you made the edits above, undo each of them yourself with: git checkout $base -- <file>; other active changes are someone else's work and stay exactly as they are"; exit 1; }

command:. .gnomish/lib/task-change.sh; proposal="$change/proposal.md"; for section in '## Why' '## What Changes' '## Goals' '## Non-Goals' '## Requirements' '## Success Metrics'; do
  grep -q "^$section" "$proposal" || { echo "$proposal has no '$section' section — see .claude/rules/proposal-format.md"; exit 1; };
done; grep -qE '(^|[^A-Za-z])FR[0-9]+' "$proposal" || { echo "$proposal declares no FR<n> requirement id — every requirement needs one, see .claude/rules/traceability.md"; exit 1; }; grep -qE '(^|[^A-Za-z])M[0-9]+' "$proposal" || { echo "$proposal declares no M<n> success metric id — see .claude/rules/traceability.md"; exit 1; }

